-- HOLIDAY SCENARIOS (from 005)
-- ==========================================

UPDATE public.scenarios SET
  description_tr = 'Sevgililer Günü''nde akşam yemeği yerine tamamen tatlılara odaklanan romantik bir gece planlayın. İki gün öncesinden hazırlığa başlayın. Menünüzü oluşturun: çikolatalı lav kek, çilekli krep, çikolata fondue istasyonu, mini cheesecake''ler ve makaron kulesi. Malzemeleri taze olarak temin edin; çikolata için kaliteli kuvertür, meyveler için mevsiminde çilek ve ahududu tercih edin. Sunumu özel kılın: katlı pasta standı kullanın, tatlıların üzerine yenilebilir çiçekler ve altın tozu serpin. Masayı kırmızı ve pembe tonlarında dekore edin: gül yaprakları, mumlar ve kalp şeklinde peçeteler. Yanında soğuk şampanya veya rosé şarap servisi yapın. Fondue istasyonunu masanın ortasına kurun; çilekler, marshmallow''lar ve kek parçalarını çikolataya batırmak için uzun çatallar hazırlayın. Arka planda romantik caz müziği açın. Birlikte tatlı yapmak da romantik bir aktivite olabilir: birbirinize krep çevirtebilir veya birlikte pasta süsleyebilirsiniz. Gece boyunca her lokmada aşkınızı kutlayın.',
  description_en = 'Plan a romantic evening on Valentine''s Day that focuses entirely on desserts instead of dinner. Start preparing two days in advance. Create your menu: chocolate lava cake, strawberry crepes, a chocolate fondue station, mini cheesecakes, and a macaron tower. Source ingredients fresh; choose quality couverture for chocolate and seasonal strawberries and raspberries for fruit. Make the presentation special: use tiered cake stands, sprinkle edible flowers and gold dust on desserts. Decorate the table in red and pink tones: rose petals, candles, and heart-shaped napkins. Serve chilled champagne or rose wine alongside. Set up the fondue station in the center of the table; prepare long forks for dipping strawberries, marshmallows, and cake pieces into chocolate. Play romantic jazz music in the background. Making desserts together can also be a romantic activity: you can flip crepes for each other or decorate a cake together. Celebrate your love with every bite throughout the night.'
WHERE slug = 'valentines-dessert-bar';

UPDATE public.scenarios SET
  description_tr = 'Noel sabahı herkes uyanmadan sofraya sihir dokundurmak, tüm aile için büyülü bir deneyim yaratır. Bir gün öncesinden hazırlığa başlayın. Geceden French toast güveç tarifini hazırlayın: brioche ekmeği, yumurta, süt, tarçın ve vanilya karışımına yatırın ve buzdolabına koyun; sabah sadece fırına atacaksınız. Sıcak çikolata barı için malzemeleri hazırlayın: farklı çikolata çeşitleri, mini marshmallow''lar, tarçın çubukları, krem şanti ve çikolata rendesi. Somon tabağı için füme somon, krem peynir, kapari ve limon dilimlerini hazır edin. Noel sabahı herkes uyanmadan sessizce kalkın: French toast''u fırına koyun, sıcak çikolatayı ısıtın, sofraya Noel temalı örtü serin. Masayı çam dalları, kırmızı mumlar ve küçük Noel süsleriyle dekore edin. Her tabağın yanına küçük bir hediye veya çikolata koyun. Aile uyanıp mutfağa geldiğinde, hazır olan sihirli sofraya şaşkınlıkla baksınlar. Bu an, Noel''in gerçek büyüsünü yaşatır.',
  description_en = 'Adding magic to the table before anyone wakes up on Christmas morning creates an enchanting experience for the whole family. Start preparing the day before. Prepare the overnight French toast casserole recipe: soak brioche bread in a mixture of eggs, milk, cinnamon, and vanilla, then refrigerate; in the morning you just pop it in the oven. Prepare ingredients for a hot cocoa bar: different chocolate varieties, mini marshmallows, cinnamon sticks, whipped cream, and chocolate shavings. For the salmon board, have smoked salmon, cream cheese, capers, and lemon slices ready. On Christmas morning, quietly wake up before everyone: put the French toast in the oven, heat the hot chocolate, spread a Christmas-themed tablecloth. Decorate the table with pine branches, red candles, and small Christmas ornaments. Place a small gift or chocolate next to each plate. When the family wakes up and comes to the kitchen, let them gaze in wonder at the magical table that awaits. This moment brings the true magic of Christmas to life.'
WHERE slug = 'christmas-morning-brunch';

UPDATE public.scenarios SET
  description_tr = 'Yılbaşı geri sayım ziyafeti, gece yarısına kadar her saatte farklı bir yemek çeşidi sunarak kutlamayı bir gastronomi şölenine dönüştürür. Üç gün öncesinden planlamaya başlayın. Akşam yediden gece yarısına kadar beş saatlik bir menü oluşturun: birinci saat meze ve kokteyl, ikinci saat çorba ve sıcak ekmek, üçüncü saat ara sıcak ve şarap, dördüncü saat ana yemek ve özel içecek, beşinci saat tatlı ve şampanya. Her saat için farklı bir kokteyl veya içecek eşleştirmesi yapın. Her servis arası eğlenceli aktiviteler planlayın: birinci saatte yılın en iyi anılarını paylaşın, ikinci saatte tombala oynayın, üçüncü saatte müzikli sandalye yapın, dördüncü saatte yeni yıl dilek kartlarını yazın. Son saatte masaya şampanya bardaklarını dizin ve dilek kartlarını hazırlayın. Gece yarısına beş kala geri sayım başlasın: herkes ayağa kalksın, bardakları kaldırsın. Sıfırda şampanyalar patlasın ve herkes dileklerini yüksek sesle okusun!',
  description_en = 'A New Year''s Eve countdown feast transforms the celebration into a gastronomic extravaganza by serving a different course every hour until midnight. Start planning three days in advance. Create a five-hour menu from seven in the evening to midnight: first hour appetizers and cocktails, second hour soup and warm bread, third hour hot starters and wine, fourth hour main course and special drinks, fifth hour dessert and champagne. Pair a different cocktail or beverage with each hour. Plan fun activities between each service: share the year''s best memories in the first hour, play tombola in the second, musical chairs in the third, write New Year wish cards in the fourth. In the final hour, line up champagne glasses on the table and prepare the wish cards. Five minutes to midnight, start the countdown: everyone stands up and raises their glasses. At zero, pop the champagne and have everyone read their wishes out loud!'
WHERE slug = 'new-year-countdown-feast';

UPDATE public.scenarios SET
  description_tr = 'Songkran Su Festivali, Tayland''ın renkli Yeni Yıl geleneğinden ilham alarak bahçenizi eğlenceli bir su parkına dönüştüren enerji dolu bir etkinliktir. İki gün öncesinden hazırlığa başlayın. Su tabancaları, su balonları ve plastik havuz satın alın; her misafir için en az bir su tabancası ayırın. Bahçeye su kaydırağı kurun: uzun bir branda üzerine sabun ve su dökerek kaygan bir yüzey oluşturun. Müzik sistemi hazırlayın ve tropikal müzik playlist''i oluşturun. Tayland temasını tamamlamak için renkli çiçek çelenkleri hazırlayın ve misafirlere dağıtın. Atıştırmalık istasyonu kurun: taze meyve şişleri, limonata, hindistancevizi suyu ve Tayland usulü bahar rulolarını. Herkesin ıslak kıyafetler giymesini ve yedek kıyafet getirmesini önceden bildirin. Festival başladığında kuralları açıklayın: herkes herkesi ıslatabilir, su balonları serbest! Takım yarışmaları düzenleyin: en çok su balonu yakalayan takım kazanır. Çocuklar ve yetişkinler birlikte eğlensin; bu festival yazın en eğlenceli anısı olacaktır.',
  description_en = 'Songkran Water Festival is an energy-filled event inspired by Thailand''s colorful New Year tradition that transforms your garden into a fun water park. Start preparing two days in advance. Buy water guns, water balloons, and a plastic pool; set aside at least one water gun per guest. Set up a water slide in the garden: create a slippery surface by pouring soap and water on a long tarp. Prepare a music system and create a tropical music playlist. Complete the Thai theme by making colorful flower garlands and distributing them to guests. Set up a snack station: fresh fruit skewers, lemonade, coconut water, and Thai-style spring rolls. Notify everyone in advance to wear clothes that can get wet and bring a change of clothes. When the festival starts, explain the rules: everyone can splash everyone, water balloons are fair game! Organize team competitions: the team that catches the most water balloons wins. Let children and adults have fun together; this festival will be the most fun memory of the summer.'
WHERE slug = 'songkran-water-festival';

UPDATE public.scenarios SET
  description_tr = 'Fas Riad Yemek Gecesi, yemek odanızı otantik bir Fas riad''ına dönüştürerek egzotik bir gastronomi deneyimi sunar. Üç gün öncesinden hazırlığa başlayın. Dekorasyon için yer minderleri, renkli kilimler, pirinç fenerler ve Fas tarzı tabaklar temin edin. Masayı yere yakın kurun ve etrafına büyük yastıklar dizin. Menünüzü planlayın: klasik Fas tagine''i (tavuk veya kuzu ile limon ve zeytin), yanında tereyağlı kuskus, Fas usulü havuç salatası ve başlangıç olarak humus ve pide. Tatlı olarak bal ve cevizli baklava veya Fas kurabiyesi hazırlayın. İçecek olarak taze nane çayı demleyin ve geleneksel yüksekten dökme servisini yapın. Baharat çarşısı atmosferi için tarçın çubukları, yıldız anason ve kurutulmuş gül yapraklarını masaya serpin. Arka planda Arap-Endülüs müziği açın. Misafirlere yemekten önce gül suyu ile el yıkama ritüeli yapın. Her yemeğin hikayesini ve Fas kültüründeki yerini anlatarak sofraya derinlik katın.',
  description_en = 'Moroccan Riad Dinner Night offers an exotic gastronomic experience by transforming your dining room into an authentic Moroccan riad. Start preparing three days in advance. For decoration, obtain floor cushions, colorful rugs, brass lanterns, and Moroccan-style plates. Set the table low to the ground and arrange large pillows around it. Plan your menu: classic Moroccan tagine (chicken or lamb with lemon and olives), buttery couscous on the side, Moroccan-style carrot salad, and hummus with pita as a starter. For dessert, prepare baklava with honey and walnuts or Moroccan cookies. Brew fresh mint tea as a beverage and perform the traditional high-pour service. For a spice bazaar atmosphere, scatter cinnamon sticks, star anise, and dried rose petals on the table. Play Arab-Andalusian music in the background. Before the meal, perform a hand-washing ritual with rose water for guests. Add depth to the table by telling the story of each dish and its place in Moroccan culture.'
WHERE slug = 'moroccan-riad-dinner';

UPDATE public.scenarios SET
  description_tr = 'Fondue Keyif Gecesi, soğuk kış akşamlarında sevdiklerinizle sıcak ve samimi bir paylaşım deneyimi yaşamanın en lezzetli yoludur. Bir gün öncesinden hazırlığa başlayın. İki ayrı fondue seti hazırlayın: biri peynir, diğeri çikolata için. Peynir fondue için kaliteli gruyère ve emmental peyniri, beyaz şarap ve sarımsak alın. Yanına daldırmak için küp küp kesilmiş ekmek, elma dilimleri, brokoli çiçekleri ve küçük patatesler hazırlayın. Çikolata fondue için bitter ve sütlü çikolata karışımı eritin; yanına çilek, muz dilimleri, marshmallow, kuru kayısı ve bisküvi çubukları dizin. Ortamı keyifli kılmak için battaniyeler ve yumuşak yastıklar yayın, mumları yakın ve şömine varsa ateşi canlandırın. Sıcak şarap veya elmalı sıcak punch hazırlayın. Arka planda akustik veya caz müziği açın. Uzun fondue çatallarıyla birlikte yemek yemenin yarattığı paylaşım ritüelinin tadını çıkarın. Bu gece, sohbetin ve lezzetin birleştiği huzurlu bir an olacaktır.',
  description_en = 'Cozy Fondue Night is the most delicious way to share a warm and intimate experience with loved ones on cold winter evenings. Start preparing the day before. Set up two separate fondue sets: one for cheese, one for chocolate. For cheese fondue, buy quality gruyere and emmental cheese, white wine, and garlic. Prepare cubed bread, apple slices, broccoli florets, and small potatoes for dipping. For chocolate fondue, melt a mix of dark and milk chocolate; arrange strawberries, banana slices, marshmallows, dried apricots, and cookie sticks alongside. Spread blankets and soft pillows to make the atmosphere cozy, light candles, and if there is a fireplace, stoke the fire. Prepare mulled wine or hot apple punch. Play acoustic or jazz music in the background. Enjoy the sharing ritual created by eating together with long fondue forks. This night will be a peaceful moment where conversation and flavor come together.'
WHERE slug = 'fondue-cozy-night';

UPDATE public.scenarios SET
  description_tr = 'İngiliz usulü çay partisi, zarif ve nostaljik bir atmosferde misafirlerinizi ağırlamanın en şık yoludur. İki gün öncesinden hazırlığa başlayın. Üç katlı servis tepsileri temin edin; varsa vintage porselen fincanlar ve tabaklar kullanın. Alt kata parmak sandviçleri yerleştirin: salatalıklı, yumurtalı, füme somonlu ve krem peynirli çeşitler hazırlayın. Orta kata taze pişmiş scone''lar koyun; yanında clotted cream ve çilek reçeli sunun. Üst kata petit four''lar, mini eklerler ve ince dilimlenmiş kekler dizin. Çay seçkisi oluşturun: Earl Grey, English Breakfast, Darjeeling ve papatya çayı. Her çay çeşidini etiketli çaydanlıklarda sunun. Masayı beyaz örtü, dantel peçeteler ve taze çiçek aranjmanlarıyla süsleyin. Misafirlerden şık giyinmelerini isteyin; isterseniz şapka teması ekleyebilirsiniz. Klasik müzik veya hafif piyano melodileri çalın. Çay servisinde geleneksel İngiliz kurallarını uygulayın: önce süt mü çay mı tartışmasını eğlenceli bir şekilde başlatın. Bu zarif davet, günlük yaşamın koşuşturmasından uzak dingin bir kaçış olacaktır.',
  description_en = 'A British-style tea party is the most elegant way to host your guests in a refined and nostalgic atmosphere. Start preparing two days in advance. Obtain three-tiered serving trays; use vintage porcelain cups and plates if available. Place finger sandwiches on the bottom tier: prepare cucumber, egg, smoked salmon, and cream cheese varieties. Place freshly baked scones on the middle tier; serve with clotted cream and strawberry jam. Arrange petit fours, mini eclairs, and thinly sliced cakes on the top tier. Create a tea selection: Earl Grey, English Breakfast, Darjeeling, and chamomile tea. Serve each tea variety in labeled teapots. Decorate the table with a white tablecloth, lace napkins, and fresh flower arrangements. Ask guests to dress elegantly; you can add a hat theme if desired. Play classical music or light piano melodies. Apply traditional British rules during tea service: start the fun debate of milk first or tea first. This elegant gathering will be a peaceful escape from the rush of daily life.'
WHERE slug = 'afternoon-tea-party';

UPDATE public.scenarios SET
  description_tr = 'Aile Kökeni Yemek Gecesi, her aile kolunun kendi kökeninden bir yemek getirerek kültürel zenginliği kutladığı anlamlı ve keşif dolu bir etkinliktir. On gün öncesinden planlamaya başlayın. Her aile koluna haber verin: kendi kökenlerinden veya memleketlerinden bir yemek hazırlamalarını isteyin. Aynı zamanda o yemeğin hikayesini, tarihin nereden geldiğini ve aile için ne anlam ifade ettiğini anlatmaya hazırlanmalarını söyleyin. Mekanı dünya haritasıyla süsleyin ve her ailenin kökenini harita üzerinde işaretleyin. Eski aile fotoğraflarını toplayın ve masanın ortasına bir fotoğraf albümü koyun. Göç hikayelerini anlatan kısa kartlar hazırlayın. Yemek sırasında her aile sırayla yemeğini tanıtsın: bu tarif kimden öğrenildi, hangi şehirde yaygın, bayramlarda mı yapılır? Çocukların da katılması için "Ailem Ağacı" çizim etkinliği düzenleyin. Gecenin sonunda herkesin bir soy ağacı dalına ismini yazarak ortak bir aile ağacı oluşturun. Bu gece, köklerinizi keşfetmenin ve birbirinize bağlanmanın güzel bir yoludur.',
  description_en = 'Family Heritage Dinner Night is a meaningful and discovery-filled event where each family branch celebrates cultural richness by bringing a dish from their heritage. Start planning ten days in advance. Notify each family branch: ask them to prepare a dish from their origins or hometown. Also tell them to prepare to share the story of the dish, where the recipe comes from, and what it means to the family. Decorate the venue with a world map and mark each family''s origin on it. Collect old family photos and place a photo album in the center of the table. Prepare short cards telling migration stories. During dinner, have each family introduce their dish in turn: who taught this recipe, which city is it popular in, is it made during holidays? Organize a "My Family Tree" drawing activity for children to participate. At the end of the night, create a shared family tree by having everyone write their name on a branch. This night is a beautiful way to discover your roots and connect with each other.'
WHERE slug = 'family-heritage-dinner';
